#!/usr/bin/env node
/**
 * TRED — les Facher : le niveau entre le semestre et les documents.
 *
 *     node <chemin>\tred-facher.mjs
 *
 * Hierarchie : Semester -> Fach -> Documents.
 *
 * Cote serveur
 *   - table `subject` (id, userId, semesterId, name, color, position)
 *   - colonne `document.subject_id`, nullable : un document non classe reste
 *     un document depose. Obliger a choisir au televersement fait renoncer
 *     au televersement.
 *   - routes subjects.list / create / rename / remove / assign. Chaque
 *     ecriture recoupe userId : `authed` dit QUI appelle, pas ce qu'il possede.
 *   - le tuteur accepte une portee `subjectId`, entre le document et le
 *     semestre. Poser une question a un Fach cherche dans le script, les
 *     exercices et les anciennes klausuren ensemble.
 *   - supprimer un Fach NE SUPPRIME PAS ses documents : ils repassent en
 *     "non classe". Supprimer une etagere ne brule pas les livres.
 *   - le partage de semestre recopie les Facher et re-associe les documents.
 *   - RGPD : `subject` ajoutee a l'effacement et a l'export.
 *
 * Cote web
 *   - une rangee de puces sous les semestres : filtrer, creer, supprimer.
 *   - rangement en lot depuis la barre de selection multiple.
 *   - dans le chat, un selecteur de Fach a cote de la portee.
 *
 * Le mobile ne connait pas encore les Facher : il continue de lister les
 * documents comme avant. C'est la suite.
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) {
  console.error("\n  x  Depot introuvable.\n");
  process.exit(1);
}

const FILES = {
"packages/web/src/api/database/schema.ts": "",
"packages/web/src/api/index.ts": "",
"packages/web/src/api/lib/gdpr.ts": "",
"packages/web/src/api/routes/subjects.ts": "",
"packages/web/src/api/routes/documents.ts": "",
"packages/web/src/api/routes/semesters.ts": "",
"packages/web/src/web/components/subject-bar.tsx": "",
"packages/web/src/web/queries/subjects.ts": "",
"packages/web/src/web/pages/dashboard.tsx": "",
"packages/web/src/web/pages/chat.tsx": "",
"packages/web/src/web/i18n/messages/de.ts": "",
"packages/web/src/web/i18n/messages/en.ts": "",
"packages/web/src/web/i18n/messages/fr.ts": "",
"packages/web/src/web/i18n/messages/es.ts": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}

console.log(`
  ETAPE OBLIGATOIRE — la base doit suivre :

      node migre-base.mjs

  Sans elle, la table subject et la colonne document.subject_id n'existent
  pas, et le tableau de bord tombera en erreur des qu'un semestre est ouvert.
`);
